-- PostgreSQL schema kept aligned with FoodDelivery.Api/Migrations/20261110205112_InitialCreate.cs.
-- Table and column identifiers are quoted to preserve EF Core's PostgreSQL casing.
CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

CREATE TABLE IF NOT EXISTS "Owners" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(150) NOT NULL,
    "Age" integer NOT NULL,
    "Phone" character varying(30) NOT NULL,
    "Email" character varying(254) NOT NULL,
    CONSTRAINT "PK_Owners" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Days" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(20) NOT NULL,
    CONSTRAINT "PK_Days" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Restaurants" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(200) NOT NULL,
    "Address" character varying(300) NOT NULL,
    "Capacity" integer NOT NULL,
    "DateOfAdd" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
    "TimeOpen" time without time zone,
    "TimeClose" time without time zone,
    "Nationality" character varying(100),
    "Budget" numeric(18,2) NOT NULL,
    "OwnerId" integer NOT NULL,
    CONSTRAINT "PK_Restaurants" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Restaurants_Capacity_Positive" CHECK ("Capacity" > 0),
    CONSTRAINT "FK_Restaurants_Owners_OwnerId" FOREIGN KEY ("OwnerId")
        REFERENCES "Owners" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "Chefs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(150) NOT NULL,
    "Speciality" character varying(100) NOT NULL,
    "Experience" integer NOT NULL,
    "Salary" numeric(18,2) NOT NULL,
    "RestaurantId" integer,
    CONSTRAINT "PK_Chefs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Chefs_Restaurants_RestaurantId" FOREIGN KEY ("RestaurantId")
        REFERENCES "Restaurants" ("Id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "Candidatures" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Salary" numeric(18,2) NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
    "ChefId" integer NOT NULL,
    "RestaurantId" integer NOT NULL,
    CONSTRAINT "PK_Candidatures" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Candidatures_Chefs_ChefId" FOREIGN KEY ("ChefId")
        REFERENCES "Chefs" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Candidatures_Restaurants_RestaurantId" FOREIGN KEY ("RestaurantId")
        REFERENCES "Restaurants" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "RestaurantOperatingDays" (
    "RestaurantId" integer NOT NULL,
    "DayId" integer NOT NULL,
    CONSTRAINT "PK_RestaurantOperatingDays" PRIMARY KEY ("RestaurantId", "DayId"),
    CONSTRAINT "FK_RestaurantOperatingDays_Restaurants_RestaurantId" FOREIGN KEY ("RestaurantId")
        REFERENCES "Restaurants" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_RestaurantOperatingDays_Days_DayId" FOREIGN KEY ("DayId")
        REFERENCES "Days" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "RestaurantOffDays" (
    "RestaurantId" integer NOT NULL,
    "DayId" integer NOT NULL,
    CONSTRAINT "PK_RestaurantOffDays" PRIMARY KEY ("RestaurantId", "DayId"),
    CONSTRAINT "FK_RestaurantOffDays_Restaurants_RestaurantId" FOREIGN KEY ("RestaurantId")
        REFERENCES "Restaurants" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_RestaurantOffDays_Days_DayId" FOREIGN KEY ("DayId")
        REFERENCES "Days" ("Id") ON DELETE RESTRICT
);

-- Commerce entities added by AddClientsProductsPurchasesOrders.
CREATE TABLE IF NOT EXISTS "Clients" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(150) NOT NULL,
    "City" character varying(100) NOT NULL,
    "Nationality" character varying(100) NOT NULL,
    "Budget" numeric(18,2) NOT NULL,
    "Weight" numeric(8,2) NOT NULL,
    "Status" character varying(20) NOT NULL,
    CONSTRAINT "PK_Clients" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Products" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(150) NOT NULL,
    "Type" character varying(100) NOT NULL,
    "Stock" integer NOT NULL,
    "Price" numeric(18,2),
    "CookDate" timestamp with time zone NOT NULL,
    "ChefId" integer NOT NULL,
    CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Products_Stock_NonNegative" CHECK ("Stock" >= 0),
    CONSTRAINT "CK_Products_Price_Positive_WhenSet" CHECK ("Price" IS NULL OR "Price" > 0),
    CONSTRAINT "FK_Products_Chefs_ChefId" FOREIGN KEY ("ChefId")
        REFERENCES "Chefs" ("Id") ON DELETE RESTRICT
);

-- Also upgrade an existing database volume created before product pricing was introduced.
ALTER TABLE "Products" ADD COLUMN IF NOT EXISTS "Price" numeric(18,2);
DO $pricing$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'CK_Products_Price_Positive_WhenSet'
          AND conrelid = '"Products"'::regclass
    ) THEN
        ALTER TABLE "Products"
            ADD CONSTRAINT "CK_Products_Price_Positive_WhenSet"
            CHECK ("Price" IS NULL OR "Price" > 0);
    END IF;
END $pricing$;

CREATE TABLE IF NOT EXISTS "Orders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" timestamp with time zone NOT NULL,
    "Time" time without time zone NOT NULL,
    "Status" character varying(20) NOT NULL,
    "ClientId" integer NOT NULL,
    "ChefId" integer NOT NULL,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Orders_Clients_ClientId" FOREIGN KEY ("ClientId")
        REFERENCES "Clients" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Orders_Chefs_ChefId" FOREIGN KEY ("ChefId")
        REFERENCES "Chefs" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "Purchases" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" timestamp with time zone NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "Quantity" integer NOT NULL,
    "ClientId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    CONSTRAINT "PK_Purchases" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Purchases_Clients_ClientId" FOREIGN KEY ("ClientId")
        REFERENCES "Clients" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Purchases_Products_ProductId" FOREIGN KEY ("ProductId")
        REFERENCES "Products" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "OrderProducts" (
    "OrderId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    CONSTRAINT "PK_OrderProducts" PRIMARY KEY ("OrderId", "ProductId"),
    CONSTRAINT "FK_OrderProducts_Orders_OrderId" FOREIGN KEY ("OrderId")
        REFERENCES "Orders" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_OrderProducts_Products_ProductId" FOREIGN KEY ("ProductId")
        REFERENCES "Products" ("Id") ON DELETE RESTRICT
);

-- Mark EF migrations as applied so `dotnet ef database update` doesn't recreate tables.
INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES
    ('20261110205112_InitialCreate', '6.0.36'),
    ('20261114143456_AddClientsProductsPurchasesOrders', '6.0.36'),
    ('20261121180000_AddProductPrice', '6.0.36')
ON CONFLICT ("MigrationId") DO NOTHING;
